CREATE TABLE dbo.ProductEmbeddings
(
    ProductId  INT NOT NULL PRIMARY KEY REFERENCES dbo.Products(ProductId),
    Embedding  VECTOR(1536) NOT NULL,            -- float32, ~6 KB
    Compact    VECTOR(1536, float16) NULL         -- ~3 KB
);

DECLARE @v VECTOR(3) = '[0.1, 2, 30]';
SELECT CAST(@v AS NVARCHAR(MAX)) AS as_text,   -- scientific notation
       CAST(@v AS JSON)          AS as_json;   -- decimal notation

CREATE VECTOR INDEX vix_ProductEmbeddings
    ON dbo.ProductEmbeddings (Embedding)
    WITH (METRIC = 'cosine', TYPE = 'DiskANN', MAXDOP = 8);

SELECT i.name, JSON_VALUE(v.build_parameters, '$.Version') AS index_version
FROM sys.vector_indexes AS v
JOIN sys.indexes AS i ON i.object_id = v.object_id AND i.index_id = v.index_id;
